CREATE view [SEARCH_ON SANAD] as SELECT     dbo.DEED_DTL.N_S, dbo.DEED_DTL.RADIF, dbo.DEED_DTL.HES_K, dbo.DEED_DTL.HES_M, dbo.DEED_DTL.SHARH, dbo.DEED_DTL.BED, dbo.DEED_DTL.BES, dbo.DEED_DTL.N_SERI, dbo.DEED_DTL.BANK, dbo.DEED_DTL.NUMBER, dbo.DEED_DTL.TAG, dbo.DEED_HED.DATE_S, dbo.TDETA_HES.TNUMBER, dbo.TDETA_HES.NAME, dbo.DEED_HED.NO_S, dbo.DEED_DTL.HES_T2, dbo.DEED_DTL.HES_T3,  dbo.DEED_DTL.HES_T4, dbo.DEED_DTL.HES, dbo.CUST_HESAB.NAME AS namcust, dbo.DETA_HES.NAME AS namemoin, dbo.TOTA_HES.NAME AS namkol, dbo.CUST_HESAB.NAME + N' - ' + dbo.DETA_HES.NAME + N' - ' + dbo.TOTA_HES.NAME AS namhes  FROM dbo.DEED_HED INNER JOIN   dbo.TDETA_HES INNER JOIN   dbo.DEED_DTL ON dbo.TDETA_HES.TNUMBER = dbo.DEED_DTL.HES_T AND dbo.TDETA_HES.NUMBER = dbo.DEED_DTL.HES_M AND   dbo.TDETA_HES.N_KOL = dbo.DEED_DTL.HES_K AND dbo.TDETA_HES.TNUMBER = dbo.DEED_DTL.HES_T AND  dbo.TDETA_HES.NUMBER = dbo.DEED_DTL.HES_M AND dbo.TDETA_HES.N_KOL = dbo.DEED_DTL.HES_K ON  dbo.DEED_HED.N_S = dbo.DEED_DTL.N_S INNER JOIN  dbo.CUST_HESAB ON dbo.DEED_DTL.HES = dbo.CUST_HESAB.hes INNER JOIN  dbo.DETA_HES ON dbo.TDETA_HES.N_KOL = dbo.DETA_HES.N_KOL AND dbo.TDETA_HES.NUMBER = dbo.DETA_HES.NUMBER INNER JOIN  dbo.TOTA_HES ON dbo.TDETA_HES.N_KOL = dbo.TOTA_HES.NUMBER
